"""Static and menu screens for the Space Fractions desktop UI."""

import random
import tkinter as tk
from tkinter import ttk


class BaseScreen(tk.Frame):
    """Common base class: every screen receives the root ``App``."""

    def __init__(self, app, **kwargs):
        super().__init__(app, **kwargs)
        self.app = app
        self.configure(bg="#0b1026")


class IntroScreen(BaseScreen):
    """Skippable animated intro that stands in for the introductory movie."""

    def __init__(self, app):
        super().__init__(app)
        self._cancelled = False
        self._after_id = None
        self._step = 0
        self.canvas = tk.Canvas(self, bg="#0b1026", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)

        for _ in range(60):
            x = random.randint(0, 800)
            y = random.randint(0, 600)
            self.canvas.create_oval(x, y, x + 2, y + 2, fill="white", outline="")

        self.canvas.create_text(400, 110, text="Space Fractions", fill="#7fd8ff", font=("Helvetica", 34, "bold"))
        self.canvas.create_text(400, 150, text="A fraction adventure for sixth-grade astronauts", fill="#d0d7ff", font=("Helvetica", 14))
        self.rocket = self.canvas.create_oval(40, 300, 84, 344, fill="#f4b400", outline="")
        self.flame = self.canvas.create_polygon(40, 322, 16, 332, 40, 342, fill="#ff5722", outline="")
        self.canvas.create_text(400, 540, text="Click anywhere or press any key to skip", fill="#9aa0b5", font=("Helvetica", 12))
        self.skip = tk.Button(self, text="Skip intro", command=self._finish)
        self.skip.place(relx=1.0, rely=1.0, anchor="se", x=-10, y=-10)

        self.bind("<Button-1>", lambda _event: self._finish())
        self.bind("<Key>", lambda _event: self._finish())
        self.focus_set()
        self._animate()

    def _animate(self):
        if self._cancelled:
            return
        self._step += 1
        if self._step < 150:
            self.canvas.move(self.rocket, 4, 0)
            self.canvas.move(self.flame, 4, 0)
            self._after_id = self.after(30, self._animate)
        else:
            self._finish()

    def _finish(self):
        if self._cancelled:
            return
        self._cancelled = True
        if self._after_id is not None:
            self.after_cancel(self._after_id)
        self.app.show_menu()


class MenuScreen(BaseScreen):
    def __init__(self, app):
        super().__init__(app)
        tk.Label(self, text="Space Fractions", bg="#0b1026", fg="#7fd8ff", font=("Helvetica", 32, "bold")).pack(pady=(50, 10))
        tk.Label(self, text="Main menu", bg="#0b1026", fg="#d0d7ff", font=("Helvetica", 14)).pack(pady=4)

        name_frame = tk.Frame(self, bg="#0b1026")
        name_frame.pack(pady=8)
        tk.Label(name_frame, text="Player name:", bg="#0b1026", fg="white").pack(side="left")
        self.name_var = tk.StringVar(value=self.app.user_service.get_username())
        tk.Entry(name_frame, textvariable=self.name_var, width=24).pack(side="left", padx=6)

        for text, command in (
            ("Play", self._play),
            ("Help", self.app.show_help),
            ("High scores", self.app.show_high_scores),
            ("Admin", self.app.show_admin),
            ("Exit", self.app.destroy),
        ):
            tk.Button(self, text=text, width=22, command=command).pack(pady=5)

    def _play(self):
        name = self.name_var.get().strip() or "Player"
        self.app.user_service.set_username(name)
        self.app.start_game()


class HelpScreen(BaseScreen):
    HELP_TEXT = (
        "How to play\n\n"
        "Answer each multiple-choice fraction question by clicking an option.\n"
        "The game covers addition, subtraction, multiplication, comparison and\n"
        "simplification of fractions. You score one point for each correct answer.\n\n"
        "Controls\n"
        "• Play: start a new game\n"
        "• Pause/Resume: stop and resume the current game\n"
        "• Help: show this screen\n"
        "• High scores: view the best results\n"
        "• Admin: add, edit or delete questions\n"
    )

    def __init__(self, app):
        super().__init__(app)
        tk.Label(self, text="Help", bg="#0b1026", fg="#7fd8ff", font=("Helvetica", 24, "bold")).pack(pady=12)
        tk.Label(self, text=self.HELP_TEXT, bg="#0b1026", fg="white", justify="left", font=("Helvetica", 12)).pack(padx=24, pady=8, anchor="w")
        tk.Button(self, text="Back to menu", command=self.app.show_menu).pack(pady=12)


class HighScoresScreen(BaseScreen):
    def __init__(self, app):
        super().__init__(app)
        tk.Label(self, text="High scores", bg="#0b1026", fg="#7fd8ff", font=("Helvetica", 24, "bold")).pack(pady=12)
        columns = ("player", "score", "total", "when")
        tree = ttk.Treeview(self, columns=columns, show="headings", height=10)
        for col, width in (("player", 160), ("score", 80), ("total", 80), ("when", 220)):
            tree.heading(col, text=col.capitalize())
            tree.column(col, width=width, anchor="center")
        for entry in self.app.score_repo.list_high_scores(10):
            tree.insert("", "end", values=(entry.player_name, entry.score, entry.total_questions, entry.played_at))
        tree.pack(fill="both", expand=True, padx=20, pady=8)
        tk.Button(self, text="Back to menu", command=self.app.show_menu).pack(pady=12)


class EndingScreen(BaseScreen):
    def __init__(self, app):
        super().__init__(app)
        game = self.app.game
        score = game.score if game else 0
        total = game.total_questions if game else 0
        if total > 0:
            ratio = score / total
            if ratio >= 0.8:
                feedback = "Outstanding! You are a true fraction astronaut."
            elif ratio >= 0.5:
                feedback = "Good work! A little more practice and you will reach the stars."
            else:
                feedback = "Keep practising — every launch gets you closer."
        else:
            feedback = "No questions were played."
        self.app.score_repo.save(self.app.user_service.get_username(), score, total)

        tk.Label(self, text="Mission complete", bg="#0b1026", fg="#7fd8ff", font=("Helvetica", 28, "bold")).pack(pady=30)
        tk.Label(self, text=f"Final score: {score} / {total}", bg="#0b1026", fg="white", font=("Helvetica", 18)).pack(pady=6)
        tk.Label(self, text=feedback, bg="#0b1026", fg="#d0d7ff", font=("Helvetica", 13)).pack(pady=10)
        tk.Button(self, text="Play again", width=22, command=self.app.start_game).pack(pady=6)
        tk.Button(self, text="Back to menu", width=22, command=self.app.show_menu).pack(pady=6)
